+// API keys, roles and the audit log. Keys live in the data as
+// `apiKeys: [{ key, name, role }]`. Each route needs one permission; a role
+// grants a set of permissions (docs/DATA.md, "Access").
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Permissions each role grants. */
+export const ROLES = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook"]),
+  manager: Object.freeze(["read", "cook", "manage", "audit"]),
+});
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a secret, or null when there is none. */
+export function findKey(store, secret) {
+  if (typeof secret !== "string" || secret === "") return null;
+  const wanted = digest(secret);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` grants `permission`. */
+export function allows(role, permission) {
+  return Object.hasOwn(ROLES, role) && ROLES[role].includes(permission);
+}
+
+/** Appends an audit entry (time, key name, method, path, status) and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
