+++ b/tests/access.test.js
@@ -0,0 +1,57 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  const notBearer = await raw({ path: "/items", headers: { authorization: "dev-manager-key" } });
+  assert.equal(notBearer.status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { raw, store } = app();
+  assert.equal((await raw({ path: "/items", headers: auth("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: auth("viewer") });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await raw({ path: "/audit", headers: auth("viewer") })).status, 403);
+});
+
+test("cooks cook, waste, log temperatures and count, but nothing else", async () => {
+  const { raw, handle } = app();
+  const h = auth("cook");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 }, headers: h })).status, 201);
+  assert.equal((await raw({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 }, headers: h })).status, 201);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await raw({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 }, headers: h })).status, 200);
+  assert.equal((await raw({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await raw({ method: "POST", path: "/stocktakes", body: { location: "fridge" }, headers: h })).status, 403);
+  assert.equal((await raw({ method: "POST", path: "/orders/3/send", headers: h })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited, newest first, and only managers read the audit", async () => {
+  const { raw, store } = app();
+  await raw({ path: "/items", headers: auth("cook") });
+  await raw({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 }, headers: auth("cook") });
+  await raw({ method: "POST", path: "/orders/3/send", headers: auth("cook") });
+  const res = await raw({ path: "/audit", headers: auth("manager") });
+  assert.equal(res.status, 200);
+  assert.deepEqual(
+    res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "cook (dev)", method: "POST", path: "/orders/3/send", status: 403 },
+      { keyName: "cook (dev)", method: "POST", path: "/batches/6/waste", status: 201 },
+    ],
+  );
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.equal(store.data.audit.length, 2);
+});
